// The B-4 persistence pattern (docs/spec/fsm.md, B-4) with polyspec orm on SQLite (docs/plans/fsm-v1.md, C-2). A row keeps
// the status code. A transition runs in one transaction: the row is read under its lock (for_update), the event is applied to
// the state that the caller observed, and the row is updated only when the state changed. The caller passes the same observed
// state on a retry, so a retry is Unchanged and a stale request is E_CONFLICT. The models are generated by build.rs from the root
// schema/persist.dbs into OUT_DIR. This file is a module of tests/conformance.rs, which names the machine's step (decide).

polyspec_orm::models!();

use model::Item;
use polyspec_orm::{Config, Db};
use fsm_rust::fsm::Error;

/// Why one attempt failed inside its transaction: a database error, or the machine's error, which rolls the transaction back.
#[derive(Debug)]
pub enum Failure {
    Database(polyspec_orm::Error),
    Machine(Error),
}

impl From<polyspec_orm::Error> for Failure {
    fn from(error: polyspec_orm::Error) -> Failure {
        Failure::Database(error)
    }
}

impl std::fmt::Display for Failure {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Failure::Database(error) => write!(f, "database: {error}"),
            Failure::Machine(error) => write!(f, "machine: {error}"),
        }
    }
}

/// Connects to the SQLite database of `dsn` (sqlite://<path>) and installs the persist tables in it.
pub async fn open(dsn: &str) -> polyspec_orm::Result<Db> {
    let db = model::connect(dsn, 1, Config::default()).await?;
    db.utils().schema().install(&model::SCHEMA).await?;
    Ok(db)
}

/// Stores the status code `code` as the row `id`.
pub async fn seed(db: &Db, id: i64, code: i32) -> polyspec_orm::Result<()> {
    let mut row = Item::new().connect(db).set_id(id).set_status(code);
    row.create().await?;
    Ok(())
}

/// The status code stored in the row `id`.
pub async fn fsm_of(db: &Db, id: i64) -> polyspec_orm::Result<i32> {
    Item::new().connect(db).id(id).get().await?.get_status()
}

/// One attempt of a transition on the row `id` (docs/spec/fsm.md, B-4). `decide` receives the code that the row holds and
/// returns the code of the state that the event leads to and whether the stored state changed. A changed row is written in
/// the transaction; an error of `decide` rolls the transaction back and is returned as the callback's error.
pub async fn transition(
    db: &Db,
    id: i64,
    decide: impl FnOnce(i64) -> Result<(i32, bool), Error>,
) -> Result<(i32, bool), polyspec_orm::TransactionOnceError<Failure>> {
    db.transaction_once(async || {
        let row = Item::new().connect(db).id(id).for_update().get().await?;
        let (to, changed) = decide(i64::from(row.get_status()?)).map_err(Failure::Machine)?;
        if changed {
            row.set_status(to).update(false).await?;
        }
        Ok((to, changed))
    })
    .await
}
